import{_ as o,o as a,c as t,ag as c}from"./chunks/framework.Pp2klvcf.js";const u=JSON.parse('{"title":"Mock API and requests","description":"","frontmatter":{},"headers":[],"relativePath":"en/monorepo/mock-api.md","filePath":"en/monorepo/mock-api.md","lastUpdated":1788681727000}'),s={name:"en/monorepo/mock-api.md"};function n(d,e,r,i,p,m){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="mock-api-and-requests" tabindex="-1">Mock API and requests <a class="header-anchor" href="#mock-api-and-requests" aria-label="Permalink to &quot;Mock API and requests&quot;">​</a></h1><p><code>pnpm dev:mock</code> starts the Nitro service in <code>apps/backend-mock</code> and the selected frontends. <code>pnpm dev:backend-mock</code> starts only the API. Development accounts are <code>admin / 123456</code> and <code>user / 123456</code>.</p><p>Pages call the domain client from <code>@fast-vue3/api</code>. <code>@fast-vue3/request</code> attaches the stored token, unwraps <code>{ code, message, data }</code>, and throws backend messages for failed business responses.</p><p>The mock uses the same boundary as the real server:</p><ul><li>anonymous: <code>GET /api/v1/public/**</code> and <code>POST /api/v1/public/contact</code>;</li><li>authenticated: admin APIs, <code>POST /api/v1/blog/{id}/comments</code>, and <code>POST /api/v1/payments/checkout</code>.</li></ul><p>The mock integration test launches a real Nitro listener and verifies anonymous reads, 401 responses, login, comment creation, and checkout.</p>',6)])])}const k=o(s,[["render",n]]);export{u as __pageData,k as default};
